<script setup lang="ts">
import { runPrimaryEnter, exclusiveChoiceOptions } from '@building-suit/ux'
import type { BsDocumentExtractionForm, BsJournalImportCopy, BsJournalImportField, BsJournalImportForm, BsJournalImportView } from '../types/journalImportPresentation'
defineProps<{ copy: BsJournalImportCopy; view: BsJournalImportView }>()
const form = defineModel<BsJournalImportForm>('form', { required: true })
const extraction = defineModel<BsDocumentExtractionForm>('extraction', { required: true })
const fields: BsJournalImportField[] = ['type', 'date', 'amount', 'account', 'category', 'description', 'reference', 'counterparty', 'currency', 'exchange_rate']
const emit = defineEmits<{ close: []; file: [event: Event]; template: []; paste: []; validate: []; reset: []; confirm: []; page: [direction: number]; document: [event: Event]; proposal: [event: Event]; reject: []; accept: [] }>()
function mapping(field: BsJournalImportField, value: unknown) { form.value = { ...form.value, mapping: { ...form.value.mapping, [field]: String(value ?? '') } } }
</script>
<template>
  <BsDialog :visible="view.visible" :title="copy.title" size="lg" :dirty="view.dirty" :pending="view.pending" @update:visible="value => { if (!value) emit('close') }"><template #default="{ close }"><BsStack gap="md"><BsText size="sm" tone="muted">{{ copy.subtitle }}</BsText><BsSectionSkeleton v-if="view.loading" variant="cards"/><BsStateSurface v-else-if="view.denied" state="denied" :title="copy.deniedTitle" :description="copy.deniedBody"/><BsCard v-else-if="view.upgrade" padding="lg"><BsHeading :level="2" size="body">{{ copy.upgradeTitle }}</BsHeading><BsText size="sm" tone="muted">{{ copy.upgradeBody }}</BsText><BsLink v-if="view.plansTo" :to="view.plansTo">{{ copy.plans }}</BsLink></BsCard>
    <template v-else><BsList :aria-label="copy.progress" ordered marker="none"><BsListItem v-for="(step, index) in view.steps" :key="step.id"><BsText as="span" emphasis="semibold">{{ index + 1 }}</BsText> · {{ step.label }}</BsListItem></BsList><BsText v-if="view.error" role="alert" tone="danger">{{ view.error }}</BsText>
      <BsCard v-if="view.phase === 'upload'" as="section" padding="lg"><BsHeading :level="2" size="h2">{{ copy.uploadTitle }}</BsHeading><BsText size="sm" tone="muted">{{ copy.uploadHint }}</BsText><BsFieldLabel for="csv-file">{{ copy.chooseFile }}</BsFieldLabel><BsButton @click="emit('template')">{{ copy.downloadTemplate }}</BsButton><BsText size="sm" tone="muted">{{ copy.templateHint }}</BsText><BsText size="sm" tone="muted">{{ copy.languageHint }}</BsText><BsFileInput id="csv-file" accept=".csv,text/csv" bare hide-control @change="emit('file', $event)"/><BsText size="xs" tone="muted">{{ copy.formatHint }}</BsText><BsInline aria-hidden="true"><BsText size="xs" tone="muted" emphasis="semibold">{{ copy.or }}</BsText></BsInline><BsFieldLabel for="spreadsheet-paste">{{ copy.pasteTitle }}</BsFieldLabel><BsText id="spreadsheet-paste-hint" size="sm" tone="muted">{{ copy.pasteHint }}</BsText><BsTextarea id="spreadsheet-paste" :model-value="form.paste" :placeholder="copy.pastePlaceholder" aria-describedby="spreadsheet-paste-hint" @update:model-value="form = { ...form, paste: String($event ?? '') }" @keydown="runPrimaryEnter($event, () => emit('paste'))"/><BsInline justify="end"><BsButton :disabled="!form.paste.trim()" variant="accent" @click="emit('paste')">{{ copy.reviewPaste }}</BsButton></BsInline></BsCard>
      <BsDocumentExtractionReview v-if="view.phase === 'upload'" v-model:form="extraction" :copy="view.extraction.copy" :view="view.extraction.view" @document="emit('document', $event)" @proposal="emit('proposal', $event)" @reject="emit('reject')" @accept="emit('accept')"/><BsText v-if="view.phase === 'upload' && !view.extraction.view.visible" size="sm" tone="muted">{{ copy.extractionDenied }}</BsText>
      <template v-if="view.phase === 'mapping'"><BsCard as="section" padding="lg"><BsInline wrap align="start" justify="between"><BsBox><BsHeading :level="2" size="h2">{{ copy.mappingTitle }}</BsHeading><BsText size="sm" tone="muted">{{ view.fileSummary }}</BsText></BsBox><BsButton :disabled="view.pending" size="sm" @click="emit('reset')">{{ copy.changeFile }}</BsButton></BsInline><BsGrid :columns="2" gap="md"><BsFloatingField v-for="field in fields" :key="field" :label="copy.fields[field]"><BsSelect :model-value="form.mapping[field]" :label="copy.fields[field]" :disabled="view.pending" :aria-required="view.requiredFields.includes(field)" :options="[{ value: '', label: view.requiredFields.includes(field) ? copy.selectColumn : copy.none }, ...exclusiveChoiceOptions(view.headers, Object.values(form.mapping), form.mapping[field])]" option-label="label" option-value="value" option-disabled="disabled" native @update:model-value="mapping(field, $event)"/></BsFloatingField></BsGrid></BsCard><BsCard as="section" padding="none" overflow="hidden"><BsBox padding="lg"><BsHeading :level="2" size="body">{{ copy.preview }}</BsHeading></BsBox><BsDataTable :value="view.preview" data-key="id" :label="copy.preview" :columns="view.headers.map(header => ({ key: header.value, header: header.label }))"><template v-for="header in view.headers" :key="header.value" #[`cell-${header.value}`]="{ row }">{{ row.values[header.value] || copy.dash }}</template></BsDataTable><BsInline justify="end" padding="lg"><BsButton :disabled="view.validateDisabled" variant="accent" @click="emit('validate')">{{ view.validating ? copy.validating : copy.validate }}</BsButton></BsInline></BsCard></template>
      <BsStack v-if="view.batch && (view.phase === 'validated' || view.phase === 'results')" as="section" gap="md"><BsCard padding="lg"><BsInline wrap align="start" justify="between"><BsBox><BsHeading :level="2" size="h2">{{ view.phase === 'results' ? copy.results : copy.validation }}</BsHeading><BsText size="sm" tone="muted">{{ view.filename }}</BsText></BsBox><BsStatusBadge :status="view.status"/></BsInline><BsDescriptionList :columns="3"><BsDescriptionItem v-for="metric in view.metrics" :key="metric.id" :term="metric.label">{{ metric.value }}</BsDescriptionItem></BsDescriptionList><BsUsageMeter v-if="view.phase === 'validated' && view.usage" compact :item="view.usage"/><BsInline gap="sm" wrap justify="end"><BsButton :disabled="view.phase !== 'results' && view.pending" @click="emit('reset')">{{ view.phase === 'results' ? copy.another : copy.startOver }}</BsButton><BsButton v-if="view.phase === 'validated' && view.canConfirm" :disabled="view.pending" variant="accent" @click="emit('confirm')">{{ view.confirming ? copy.confirming : copy.confirm }}</BsButton></BsInline></BsCard><BsCard padding="none" overflow="hidden"><BsInline wrap align="end" justify="between" padding="lg"><BsFloatingField :label="copy.review"><BsSelect :model-value="form.review" :label="copy.review" :options="view.reviewChoices" option-label="label" option-value="value" native @update:model-value="form = { ...form, review: String($event) }"/></BsFloatingField><BsText role="status" size="sm" tone="muted">{{ view.range }}</BsText></BsInline><BsDataTable :value="view.rows" data-key="id" :label="copy.rows" :columns="[{ key: 'rowNumber', field: 'rowNumber', header: copy.row }, { key: 'status', header: copy.status }, { key: 'type', field: 'type', header: copy.type }, { key: 'date', field: 'date', header: copy.date }, { key: 'amount', field: 'amount', header: copy.amount }, { key: 'issue', header: copy.issue }]"><template #cell-status="{ row }"><BsStatusBadge :status="row.status"/></template><template #cell-issue="{ row }">{{ row.issue || copy.dash }}</template></BsDataTable><BsInline v-if="view.paginated" gap="sm" justify="end" padding="md"><BsButton :disabled="view.previousDisabled" size="sm" @click="emit('page', -1)">{{ copy.previous }}</BsButton><BsText as="span" size="sm" tone="muted">{{ view.pageLabel }}</BsText><BsButton :disabled="view.nextDisabled" size="sm" @click="emit('page', 1)">{{ copy.next }}</BsButton></BsInline></BsCard></BsStack>
    </template><BsInline justify="end"><BsButton :disabled="view.pending" @click="close">{{ copy.close }}</BsButton></BsInline>
  </BsStack></template></BsDialog>
</template>
